import random, time, hashlib, ctypes, ctypes.util, os
size=20_480_000
random.seed(0)
plain=random.randbytes(size)

# Warm run to load libs
hashlib.sha256(plain).digest()
lib = ctypes.CDLL(ctypes.util.find_library('crypto'))
sha256 = lib.SHA256; sha256.argtypes=[ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p]

def timeit(func, loops=10):
    t=time.perf_counter();
    for _ in range(loops): func()
    return (time.perf_counter()-t)/loops

t1 = timeit(lambda: hashlib.sha256(plain).digest())
print('hashlib', t1)

def openssl_sha():
    out=(ctypes.c_ubyte*32)();
    sha256(plain, len(plain), out)
    return bytes(out)

t2 = timeit(openssl_sha)
print('ctypes openssl', t2)
